// Findings that still stop an automatic publication: wrong language, unreadable/empty text, a publisher that forbids AI use, no source link, a near-verbatim copy.
const HARD_STOP = /^(wrong_language|not_english|not_nepali|too_short|missing_headline|missing_body|missing_standfirst|headline_not_|bad_unicode|control_chars|source_restricts_ai_use|missing_provenance|close_to_source_wording|checks_pending)$/;
const LANG_NAME = { ne: 'Nepali', en: 'English' }, MAX_SRC = 14000, MAX_ATTEMPTS = 5, STALE_MIN = 10;
const strOf = v => (typeof v === 'string' ? v.trim() : ''), arrOf = v => (Array.isArray(v) ? v.filter(x => typeof x === 'string' && x.trim()).map(x => x.trim()) : []);
const setting = (k, d = null) => { const r = db.prepare('SELECT value FROM settings WHERE key=?').get(k); try { return r ? JSON.parse(r.value) : d; } catch { return d; } };
const put = (k, v) => db.prepare('INSERT INTO settings(key,value) VALUES(?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value').run(k, JSON.stringify(v));

export function buildEditionPrompt({ lang, lead, others, src, truncated, glossary, level = 'full', maxWords = null }) {
  const L = LANG_NAME[lang], ed = `{ "headline": "", "headline_alternatives": ["", ""], "standfirst": "", "body": "paragraphs separated by a blank line; optional subheadings as lines starting with '## '", "graphic_headline": "", "graphic_description": "", "social_caption": "", "short_caption": "", "seo_title": "", "meta_description": "", "keywords": [""], "hashtags": ["#"], "alt_text": "" }`;
  const system = `You are the senior editor of Everest News. You write the ${L} edition of an ORIGINAL news report from the source material you are given. Write ONLY the ${L} edition, directly in ${L}, from the source. Do not produce any other language edition.

EVIDENCE RULES (these are checked by software afterwards)
- Use ONLY the supplied source text. The original headline and the feed summary are claims to verify, not proof of what anyone said or did. No outside knowledge; no assumed causes, motives, background, statistics or consequences.
- Never invent or alter names, titles, places, dates, numbers or sources. Never invent an interview, an eyewitness, a quotation or an anonymous source.
- A direct quotation is allowed ONLY when those exact words appear in the MAIN SOURCE TEXT below (not merely in a headline or summary), attributed to the person who said them there. List every quotation in "attributed_quotes" with the speaker and the exact words as written in the source. Anything else must be paraphrased WITHOUT quotation marks.
- List the facts you rely on in "verified_facts": a short "statement" in ${L}, and "evidence" = the exact words copied from the source text that support it. Put anything you were tempted to write but cannot support in "unsupported_claims" and leave it out of the article.
- If the material cannot support a faithful report, set "source_sufficiency.level" to "insufficient" and write nothing invented. Shorter is always better than padded.
- ORIGINALITY: paraphrase. No run of 6 or more consecutive words may be taken from the source, except names, official titles and verified quotations. Other outlets are context only; attribute anything that differs.

DEPTH: the main source has ${src.words} words (${src.origin.replace('_', ' ')}). ${level === 'brief' ? `The material is SHORT: write a concise brief of at most ${maxWords} words in total for the body, stating only what the material supports. Do not pad, explain or add background.` : 'The material is substantial: keep the chronology, figures, names and context that matter. Never pad.'}
${lang === 'ne' ? `Nepali: natural, professional newsroom Nepali in Devanagari, no Hindi-influenced phrasing. Style: ${getStyle()}${glossary.length ? `\n  Glossary (mandatory): ${glossary.map(g => `${g.en} → ${g.ne}`).join('; ')}` : ''}` : `English: natural, professional newsroom English. Style: ${getStyleEn()}`}

STRUCTURE: headline (factual), 2-3 alternatives, standfirst (1-2 sentences), body (lead paragraph, then body; "## " subheadings only for 6+ paragraphs). Separate social pieces: graphic_headline (<=60 chars), graphic_description (one sentence, <=130 chars), social_caption (a short caption for social readers, NOT a copy of the article; contains the token {{ARTICLE_URL}} on its own line, then 3-5 hashtags), short_caption (<=230 chars, no link), seo_title (<=60), meta_description (<=155), keywords (4-8), hashtags, alt_text (generic, never invent what a photo shows).

OUTPUT: exactly one JSON object: { "source_sufficiency": { "level": "full|brief|insufficient", "reasons": [] }, "review_required": false, "unsupported_claims": [], "verified_facts": [ { "statement": "", "evidence": "" } ], "attributed_quotes": [ { "speaker": "", "text": "" } ], "source_urls": [], "edition": ${ed} }`;
  const extra = others.map(o => `- ${o.source}: ${o.title}${o.text ? ' — ' + o.text : ''}`).join('\n');
  const user = `Target edition language: ${L}\nSource language: ${LANG_NAME[lead.language] ?? lead.language}\nMain source outlet: ${lead.source}\nURL: ${lead.url}\nPublished: ${lead.published_at || 'unknown'}\nOriginal headline (a claim, not evidence): ${lead.title}\nSource text: ${src.origin.replace('_', ' ')}, ${src.words} words${truncated ? ' (truncated)' : ''}\n=== MAIN SOURCE TEXT ===\n${src.text.slice(0, MAX_SRC)}\n=== END ===${extra ? `\n\nOther outlets covering the same event (context only):\n${extra}` : ''}`;
  return { system, user };
}

export function parseEditionJson(text, lang) {
  let j; try { j = JSON.parse(text.trim().replace(/^```(?:json)?\s*|\s*```$/g, '')); } catch { throw new BundleError('model did not return valid JSON', { maxAttempts: 2 }); }
  const o = j.edition; if (!o || typeof o !== 'object') throw new BundleError(`the response has no ${lang} edition`, { maxAttempts: 2 });
  const e = { headline: strOf(o.headline), alternatives: arrOf(o.headline_alternatives), standfirst: strOf(o.standfirst), body: strOf(o.body), graphic_headline: strOf(o.graphic_headline), graphic_description: strOf(o.graphic_description), social_caption: strOf(o.social_caption), short_caption: strOf(o.short_caption),
    seo_title: strOf(o.seo_title), meta_description: strOf(o.meta_description), keywords: arrOf(o.keywords), hashtags: arrOf(o.hashtags).map(h => '#' + h.replace(/^#+/, '').replace(/\s+/g, '')), alt_text: strOf(o.alt_text) };
  const sufficient = j.source_assessment?.sufficient !== false && j.source_sufficiency?.level !== 'insufficient';
  if (sufficient) for (const k of ['headline', 'standfirst', 'body', 'graphic_headline', 'graphic_description', 'social_caption', 'seo_title', 'meta_description']) if (!e[k]) throw new BundleError(`the ${lang} edition has an empty ${k}; nothing was saved`, { maxAttempts: 2 });
  const quotes = [...(Array.isArray(j.quotes) ? j.quotes : []), ...(Array.isArray(j.attributed_quotes) ? j.attributed_quotes.map(q => ({ speaker: q?.speaker, source_text: q?.text ?? q?.source_text })) : [])].filter(q => q && typeof q.source_text === 'string').slice(0, 20);
  const verified = Array.isArray(j.verified_facts) ? j.verified_facts.filter(f => f && typeof f === 'object').slice(0, 40).map(f => ({ statement: strOf(f.statement), evidence: strOf(f.evidence) })) : null;
  return { e, sufficient, gaps: arrOf(j.source_assessment?.gaps ?? j.source_sufficiency?.reasons), facts: Array.isArray(j.facts) ? j.facts.slice(0, 40) : [], quotes, verified, unsupported: arrOf(j.unsupported_claims), reviewRequired: j.review_required === true };
}

// Is the text really in the requested language? (guards against the model answering in the wrong one)
export function languageOk(text, lang) {
  const letters = (text.match(/\p{L}/gu) || []).length; if (!letters) return false;
  const ne = (text.match(/\p{Script=Devanagari}/gu) || []).length / letters;
  return lang === 'ne' ? ne >= 0.6 : ne <= 0.1;
}
const sourceError = (message, reasonCode, extra = {}) => Object.assign(new Error(message), { permanent: true, reasonCode, ...extra });
const NOT_ALLOWED = new Set(['access_restricted', 'paywall_suspected', 'robots_disallowed', 'ai_input_disallowed']);
const hash = (...p) => createHash('sha256').update(p.join('\u0000')).digest('hex');
