  b.quotes = b.quotes.filter(q => hay.includes(bareT(q.source_text))); const allowSpans = cross && b.quotes.length > 0; // a translated edition may keep quotation marks only if a verified source quotation backs them
  const keep = sentence => { const spans = quoteSpans(sentence); if (spans.length && (cross ? !allowSpans : spans.some(sp => !hay.includes(bareT(sp))))) { removed.push({ why: 'quotation not in the source', text: sentence.trim().slice(0, 160) }); return false; }
    const bad = [...numbersIn(sentence)].filter(n => !known.has(n)); if (bad.length) { removed.push({ why: `figure not in the source (${bad.join(', ')})`, text: sentence.trim().slice(0, 160) }); return false; } return true; };
